namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int ForSubtotal(LoyaltyTier tier, int subtotalCents)
    {
        var points = Math.Min(BaseRate(tier) + OrderSizeBonus(subtotalCents), CeilingPoints);

        return (int)((long)subtotalCents * points / 100);
    }

    private static int BaseRate(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null)
    };

    private static int OrderSizeBonus(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0
    };
}
E
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public int For(LoyaltyTier tier, int subtotalCents)
    {
        return subtotalCents - LoyaltyDiscount.ForSubtotal(tier, subtotalCents);
    }
}
E
dotnet test CheckoutPricing.slnx 2>&1 | grep -E "error|Passed!|Failed" ; git status --short

